    aWandererH = 0xB238A8008F6525F1ULL;
    aWandererI = 0x9A849FFE447C3B9DULL;
    aWandererJ = 0x905532B03EE5B078ULL;
    aWandererK = 0xD434E7F6475C7CBCULL;

    //
    TwistExpander_Canopus_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Canopus_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Canopus_Arx::SEED_C(PARAMS_SEED);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
