    TwistExpander_Canopus_Arx::SEED_D(PARAMS_SEED);

    TwistExpander_Canopus_Arx::SEED_E(PARAMS_SEED);

    TwistExpander_Canopus_Arx::SEED_F(PARAMS_SEED);

    //

