    TwistExpander_Canopus_Arx::SEED_M(PARAMS_SEED);

    TwistExpander_Canopus_Arx::SEED_N(PARAMS_SEED);

    //
    // [KEY — sixteen key-row functions, lane splits A-P]
    //
    TwistExpander_Canopus_Arx::KEY_A_A(PARAMS_SEED);

    TwistExpander_Canopus_Arx::KEY_A_B(PARAMS_SEED);

    TwistExpander_Canopus_Arx::KEY_A_C(PARAMS_SEED);

    TwistExpander_Canopus_Arx::KEY_A_D(PARAMS_SEED);

    TwistExpander_Canopus_Arx::KEY_A_E(PARAMS_SEED);

